    [Fact]
    public void DO10_Compatible_TotalAndSymmetric() // §3.2.3
    {
        var modes = new[] { Mode.Use, Mode.Create, Mode.Release, Mode.Move, Mode.Unknown };
        foreach (var a in modes)
            foreach (var b in modes)
            {
